    assert meta['bundle_sha256']==fit['bundle_sha256'] and meta['input_data_sha256']==freeze['query_sha256'];assert sha(root/'predictions.tsv')==meta['prediction_sha256']==source['prediction_sha256'] and sha(root/'probabilities.npz')==meta['probability_sha256']==source['probability_sha256']
    pred=pd.read_csv(root/'predictions.tsv',sep='\t');d=np.load(root/'probabilities.npz');assert np.array_equal(pred.cell_id.astype(str),a.obs_names.astype(str)) and np.array_equal(d['cell_ids'],a.obs_names.astype(str)) and list(d['labels'])==labels
    p=d['probabilities'];assert p.shape==(50023,6) and np.isfinite(p).all() and np.all(p>=0) and np.allclose(p.sum(1),1,atol=1e-5);assert np.array_equal(np.array(labels)[p.argmax(1)],pred.prediction.astype(str))
    measured=metric_summary(truth,pred.prediction,p,labels);measured['macro_f1_fixed_five']=float(f1_score(truth[known],pred.prediction.to_numpy()[known],labels=five,average='macro',zero_division=0))
    for key in ['macro_f1','macro_f1_fixed_five','balanced_accuracy','evaluation_coverage','prediction_coverage','brier_multiclass','ece_10_bins']:assert np.isclose(measured[key],table.loc[name,key],atol=1e-12,rtol=0),(name,key)
    assert np.isclose(measured['macro_f1']*6,measured['macro_f1_fixed_five']*5,atol=1e-12)
