    runpath=REPORT/'runs'/f'E00_{name}_GSE151530_seed42_v1/run.json';run=json.loads(runpath.read_text());assert run['status']=='executed' and run['freeze_sha256']==sha(freeze_path) and run['source_fit_metadata_sha256']==fit['run_sha256'] and run['prediction_sha256']==source['prediction_sha256'] and run['trainable_parameters']==0
