counts=np.stack(counts);names=list(freeze['models']);rng=np.random.default_rng(42);draw=rng.integers(0,25,size=(5000,25));weights=np.stack([(draw==i).sum(1) for i in range(25)],axis=1)
def macro(cm):
    tp=np.diagonal(cm,axis1=-2,axis2=-1);den=cm.sum(-1)+cm.sum(-2);return np.divide(2*tp,den,out=np.zeros_like(tp,dtype=float),where=den>0).mean(-1)
point=macro(counts.sum(1));boot=macro(np.einsum('bd,mdij->bmij',weights,counts));pairs=pd.read_csv(out/'paired_donor_bootstrap.tsv',sep='\t').set_index('comparison');terms={name+' vs PCA':{name:1,'pca':-1} for name in ['scgpt','geneformer','geneformer_clcancer']};terms.update({'CLcancer vs base Geneformer':{'geneformer_clcancer':1,'geneformer':-1},'4096 Data gain':{'DM10':1,'DM00':-1},'4096 Model gain':{'DM01':1,'DM00':-1},'4096 Combined gain':{'DM11':1,'DM00':-1},'4096 Interaction':{'DM11':1,'DM10':-1,'DM01':-1,'DM00':1}})
for title,coefficients in terms.items():
    delta=sum(c*point[names.index(n)] for n,c in coefficients.items());sample=sum(c*boot[:,names.index(n)] for n,c in coefficients.items());row=pairs.loc[title];assert np.allclose([delta,np.quantile(sample,.025),np.quantile(sample,.975)],[row.fixed_six_macro_f1_difference,row.lower95,row.upper95],atol=1e-12,rtol=0)
